package glitch

import data.glitch_lib

# Set of bind/listen address keywords to check
bind_keywords := {"bind_address", "listen_address", "host", "ip_address", "interface", "server_bind", "endpoint", "api_bind", "dashboard_host", "database_host", "server_address", "ip", "mongodb_net_bindip", "mysql_bind_address"}

# Check if a value is 0.0.0.0 or *
is_unrestricted_bind(value) {
    value.ir_type == "String"
    regex.match("^(0\\.0\\.0\\.0|\\*)$", value.value)
} else {
    value.ir_type == "String"
    value.value == "0.0.0.0"
} else {
    value.ir_type == "String"
    value.value == "*"
}

# Recursive function to check hash values for unrestricted bind
check_hash_for_bind(hash_node) {
    walk(hash_node, [path, node])
    node.ir_type == "String"
    is_unrestricted_bind(node)
}

# Check if a variable's value contains unrestricted bind
check_variable_for_bind(var_node) {
    is_unrestricted_bind(var_node.value)
} else {
    var_node.value.ir_type == "Hash"
    check_hash_for_bind(var_node.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables (like Ansible variables)
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    # Check if variable name matches bind keywords
    bind_keywords[var.name]

    # Check if variable value is unrestricted
    check_variable_for_bind(var)

    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Service binds to 0.0.0.0 (unrestricted IP) - This may expose services broadly. (CWE-1327)"
    }
}

Glitch_Analysis[result] {
