package glitch

import data.glitch_lib

# Set of attribute names that indicate bind/listen addresses
bind_address_names := {"bind_address", "listen_address", "host", "ip_address", "interface", "server_bind", "endpoint", "ip", "bind-address", "addr", "server_address", "api_bind", "dashboard_host", "database_host"}

# Check if a value is a dangerous bind address (0.0.0.0 or *)
is_dangerous_bind(value) {
    value.ir_type == "String"
    regex.match("^(0\\.0\\.0\\.0|\\*)$", value.value)
}

# Recursive search for dangerous bind addresses in complex values (Hash, Array)
find_dangerous_bind_in_complex(value) {
    is_dangerous_bind(value)
} else {
    value.ir_type == "Hash"
    some pair in value.value
    find_dangerous_bind_in_complex(pair.value)
} else {
    value.ir_type == "Array"
    some elem in value.value
    find_dangerous_bind_in_complex(elem)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables for dangerous bind addresses
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    # Check if variable name suggests a bind address
    contains_bind_name(var.name)

    # Check the variable's value for dangerous bind address
    find_dangerous_bind_in_complex(var.value)

    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Service binds to unrestricted IP address (0.0.0.0 or *) - This may expose services broadly. (CWE-1327)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes for dangerous bind addresses
    attributes := glitch_lib.all_attributes(parent)
    attr := attributes[_]

    # Check if attribute name suggests a bind address
    contains_bind_name(attr.name)

    # Check the attribute's value for dangerous bind address
    find_dangerous_bind_in_complex(attr.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Service binds to unrestricted IP address (0.0.0.0 or *) - This may expose services broadly. (CWE-1327)"
    }
}

# Helper to check if a name contains a bind address keyword
contains_bind_name(name) {
    # Direct match for string names
    name.ir_type == "String"
    lower_name := lower(name.value)
    some bind_name in bind_address_names
    contains(lower_name, bind_name)
} else {
    # Match for variable references (e.g., :ip in Chef)
    name.ir_type == "VariableReference"
    lower_name := lower(name.value)
    some bind_name in bind_address_names
    contains(lower_name, bind_name)
} else {
    # Match for string literals used as keys (e.g., 'bind-address' in Puppet)
    name.ir_type == "String"
    lower_name := lower(name.value)
    some bind_name in bind_address_names
    contains(lower_name, bind_name)
}

